insert into public.platform_settings (key, value) values
  ('general', '{"platformName":"Carzen","currency":"EGP","supportPhone":"+20 150 000 1111","supportEmail":"hello@carzen.demo","supportHours":{"ar":"يومياً ٩:٠٠ ص – ٩:٠٠ م","en":"Daily 9:00 AM – 9:00 PM"}}'::jsonb),
  ('booking_defaults', '{"autoConfirm":false,"slotIntervalMin":30,"leadTimeMin":15,"maxAdvanceDays":7,"freeCancelMin":60,"noShowGraceMin":15,"reminderMin":45}'::jsonb),
  ('legal', '{"terms":{"ar":"باستخدام كارزن فإنك تحجز خدمة غسيل لدى مغسلة مستقلة. السعر المعروض هو سعر المغسلة، والدفع يتم في الفرع نقدًا أو بالبطاقة. يجوز إلغاء الحجز مجانًا حتى المدة الموضحة قبل الموعد. كارزن وسيط تقني ولا تملك السيارات أثناء الخدمة.","en":"Carzen lets you book a wash with an independent car wash. The price shown is the wash''s price, and payment happens at the branch by cash or card. You may cancel free of charge until the stated window before the slot. Carzen is a technology intermediary and does not take custody of the vehicle."},"privacy":{"ar":"نحتفظ برقم موبايلك واسمك وسياراتك وحجوزاتك لتشغيل الخدمة وعرضها على المغسلة التي تحجز لديها.","en":"We store your mobile number, name, cars and bookings to run the service and show them to the wash you book."}}'::jsonb),
  ('notification_templates', '[{"id":"tpl_confirmed","event":"booking.confirmed","audience":"customer","title":{"ar":"تم تأكيد حجزك","en":"Your booking is confirmed"},"body":{"ar":"حجزك {{number}} في {{branch}} يوم {{date}} مؤكد. كود الوصول: {{code}}","en":"Booking {{number}} at {{branch}} on {{date}} is confirmed. Check-in code: {{code}}"}},{"id":"tpl_reminder","event":"booking.reminder","audience":"customer","title":{"ar":"موعدك بعد قليل","en":"Your slot is coming up"},"body":{"ar":"باقي {{minutes}} دقيقة على موعدك في {{branch}}.","en":"{{minutes}} minutes until your slot at {{branch}}."}},{"id":"tpl_cancelled","event":"booking.cancelled","audience":"customer","title":{"ar":"تم إلغاء الحجز","en":"Booking cancelled"},"body":{"ar":"تم إلغاء الحجز {{number}}. السبب: {{reason}}","en":"Booking {{number}} was cancelled. Reason: {{reason}}"}},{"id":"tpl_approved","event":"application.approved","audience":"owner","title":{"ar":"تمت الموافقة على مغسلتك","en":"Your wash was approved"},"body":{"ar":"مرحبًا بك في كارزن! أكمل إعداد الفروع لتبدأ في استقبال الحجوزات.","en":"Welcome to Carzen! Finish setting up your branches to start taking bookings."}},{"id":"tpl_suspended","event":"wash.suspended","audience":"owner","title":{"ar":"تم تعليق المغسلة","en":"Wash suspended"},"body":{"ar":"تم تعليق {{wash}} مؤقتًا. السبب: {{reason}}","en":"{{wash}} was temporarily suspended. Reason: {{reason}}"}},{"id":"tpl_complaint","event":"complaint.resolved","audience":"customer","title":{"ar":"تم حل الشكوى","en":"Complaint resolved"},"body":{"ar":"تم حل الشكوى {{ticket}}: {{resolution}}","en":"Complaint {{ticket}} resolved: {{resolution}}"}}]'::jsonb),
  ('commission', '{"defaultPct":7}'::jsonb);
